// OpenGL ES (1.1 and 2.0) and EGL imports of the native libraries. Every GL function in gl_table.h (generated by
// tools/gen_gl.py) gets one hook that passes its raw argument words to library_gl.js, which converts them by kind and
// calls the page's GLES implementation (runtime/site/gles.js), shared with the Java bindings.
#include "emu.h"
#include <string.h>
#include "gl_table.h"

extern uint32_t jgl_call(int index, const uint32_t *words, int n);   // library_gl.js
extern uint32_t jegl_swap(void);

#define NGL (int)(sizeof GL_TABLE / sizeof GL_TABLE[0])
static int first_hook;

static void gl_hook(Cpu *c) {
  int i = current_hook - first_hook;
  uint32_t w[16];
  int n = GL_TABLE[i].nargs;
  for (int k = 0; k < n && k < 16; k++) w[k] = arg(c, k);
  c->r[0] = jgl_call(i, w, n);
}

// ---- EGL: one display, one config, one window surface (the page's canvas), one context
enum { DPY = 1, CFG = 1, SURF = 1, CTX = 1 };
static uint32_t egl_error = 0x3000, current_ctx, current_surf;
static int attrib(uint32_t list, uint32_t key, int dflt) {
  if (!list) return dflt;
  for (uint32_t *a = G(list); *a != 0x3038; a += 2) if (*a == key) return (int)a[1];
  return dflt;
}
static int config_attrib(uint32_t key) {
  switch (key) {
    case 0x3020: return 32;            // BUFFER_SIZE
    case 0x3021: return 8;             // ALPHA_SIZE
    case 0x3022: case 0x3023: case 0x3024: return 8;   // BLUE, GREEN, RED
    case 0x3025: return 24;            // DEPTH_SIZE
    case 0x3026: return 8;             // STENCIL_SIZE
    case 0x3027: return 0x3038;        // CONFIG_CAVEAT: NONE
    case 0x3028: return CFG;           // CONFIG_ID
    case 0x3031: return 0;             // SAMPLES
    case 0x3032: return 0;             // SAMPLE_BUFFERS
    case 0x3033: return 0x4 | 0x1;     // SURFACE_TYPE: WINDOW | PBUFFER
    case 0x3040: return 0x1 | 0x4 | 0x40;   // RENDERABLE_TYPE: ES, ES2, ES3
    case 0x3042: return 0x1 | 0x4 | 0x40;   // CONFORMANT
    case 0x302E: return 1;             // NATIVE_VISUAL_ID
    case 0x3039: case 0x303A: return 1;     // BIND_TO_TEXTURE_RGB(A)
    default: return 0;
  }
}
static void eglGetDisplay(Cpu *c) { c->r[0] = DPY; }
static void eglInitialize(Cpu *c) { if (arg(c, 1)) *(int *)G(arg(c, 1)) = 1; if (arg(c, 2)) *(int *)G(arg(c, 2)) = 4; c->r[0] = 1; }
static void eglTerminate(Cpu *c) { c->r[0] = 1; }
static void eglGetError(Cpu *c) { c->r[0] = egl_error; egl_error = 0x3000; }
static void eglChooseConfig(Cpu *c) {   // (dpy, attribs, configs, size, num)
  if (arg(c, 2) && arg(c, 3) > 0) *(uint32_t *)G(arg(c, 2)) = CFG;
  if (arg(c, 4)) *(int *)G(arg(c, 4)) = 1;
  c->r[0] = 1;
}
static void eglGetConfigs(Cpu *c) { if (arg(c, 1) && arg(c, 2) > 0) *(uint32_t *)G(arg(c, 1)) = CFG; if (arg(c, 3)) *(int *)G(arg(c, 3)) = 1; c->r[0] = 1; }
static void eglGetConfigAttrib(Cpu *c) { *(int *)G(arg(c, 3)) = config_attrib(arg(c, 2)); c->r[0] = 1; }
static void eglCreateWindowSurface(Cpu *c) { c->r[0] = SURF; }
static void eglCreatePbufferSurface(Cpu *c) { c->r[0] = SURF + 1; }
static void eglDestroySurface(Cpu *c) { c->r[0] = 1; }
static void eglCreateContext(Cpu *c) { (void)attrib(arg(c, 3), 0x3098, 1); c->r[0] = CTX; }
static void eglDestroyContext(Cpu *c) { c->r[0] = 1; }
static void eglMakeCurrent(Cpu *c) { current_surf = arg(c, 1); current_ctx = arg(c, 3); c->r[0] = 1; }
static void eglGetCurrentContext(Cpu *c) { c->r[0] = current_ctx; }
static void eglGetCurrentSurface(Cpu *c) { c->r[0] = current_surf; }
static void eglGetCurrentDisplay(Cpu *c) { c->r[0] = current_ctx ? DPY : 0; }
static void eglSwapBuffers(Cpu *c) { jegl_swap(); c->r[0] = 1; }
static void eglSwapInterval(Cpu *c) { c->r[0] = 1; }
static void eglQuerySurface(Cpu *c) {   // (dpy, surface, attribute, value*)
  uint32_t w[2] = {0, 0};
  jgl_call(-1, w, 0);   // the canvas size (library_gl.js writes w)
  int v = 0;
  switch (arg(c, 2)) {
    case 0x3057: v = (int)w[0]; break;   // WIDTH
    case 0x3056: v = (int)w[1]; break;   // HEIGHT
    case 0x3028: v = CFG; break;
    case 0x3093: v = 0x3094; break;      // SWAP_BEHAVIOR: BUFFER_DESTROYED
    default: v = 0;
  }
  *(int *)G(arg(c, 3)) = v;
  c->r[0] = 1;
}
static void eglQueryContext(Cpu *c) { *(int *)G(arg(c, 3)) = arg(c, 2) == 0x3098 ? 2 : arg(c, 2) == 0x3028 ? CFG : 0; c->r[0] = 1; }
static void eglQueryString(Cpu *c) {
  static const char *vendor = "apk2web", *version = "1.4 apk2web", *exts = "EGL_KHR_image_base EGL_ANDROID_recordable", *apis = "OpenGL_ES";
  uint32_t n = arg(c, 1);
  c->r[0] = GA(n == 0x3053 ? vendor : n == 0x3054 ? version : n == 0x3055 ? exts : n == 0x308D ? apis : "");
}
static void eglGetProcAddress(Cpu *c) {
  int is_data = 0;
  c->r[0] = host_import(G(arg(c, 0)), &is_data);
}
static void eglTrue(Cpu *c) { c->r[0] = 1; }

void gl_init(void) {
  first_hook = -1;
  for (int i = 0; i < NGL; i++) {
    int id = (int)host_add_fn(GL_TABLE[i].name, gl_hook);
    if (first_hook < 0) first_hook = id;
  }
#define E_(n) host_add_fn(#n, n)
  E_(eglGetDisplay); E_(eglInitialize); E_(eglTerminate); E_(eglGetError); E_(eglChooseConfig); E_(eglGetConfigs);
  E_(eglGetConfigAttrib); E_(eglCreateWindowSurface); E_(eglCreatePbufferSurface); E_(eglDestroySurface);
  E_(eglCreateContext); E_(eglDestroyContext); E_(eglMakeCurrent); E_(eglGetCurrentContext); E_(eglGetCurrentSurface);
  E_(eglGetCurrentDisplay); E_(eglSwapBuffers); E_(eglSwapInterval); E_(eglQuerySurface); E_(eglQueryContext);
  E_(eglQueryString); E_(eglGetProcAddress);
  host_add_fn("eglBindAPI", eglTrue); host_add_fn("eglReleaseThread", eglTrue); host_add_fn("eglWaitGL", eglTrue);
  host_add_fn("eglWaitNative", eglTrue); host_add_fn("eglWaitClient", eglTrue); host_add_fn("eglSurfaceAttrib", eglTrue);
  host_add_fn("eglPresentationTimeANDROID", eglTrue);
}
